        ["rossiya-snils-input"] = new("html", "<Field label=\"СНИЛС (Strakhovoy Nomer Individualnogo Litsevogo Scheta)\" required>\n  <RossiyaSnilsInput label=\"СНИЛС (Strakhovoy Nomer Individualnogo Litsevogo Scheta)\" value={value} required />\n  <Hint>Eleven digits, displayed as NNN-NNN-NNN CC. The first nine digits are an account number; the last two form a Modulus-101 check value computed as a weighted sum of the first nine digits (each multiplied by its position from 9 down to 1), with sums of 100 or 101 both mapping to a check value of 00.</Hint>\n  <ErrorMessage>Please enter a valid СНИЛС</ErrorMessage>\n</Field>\n", new List<ExampleVariant> {  }),
        ["rossiya-snils-view"] = new("html", "<SummaryList>\n  <SummaryListItem term=\"СНИЛС (Strakhovoy Nomer Individualnogo Litsevogo Scheta)\">\n    <RossiyaSnilsView label=\"СНИЛС (Strakhovoy Nomer Individualnogo Litsevogo Scheta)\" value={value} />\n  </SummaryListItem>\n</SummaryList>\n", new List<ExampleVariant> {  }),
        ["turkiye-tc-kimlik-numarasi-input"] = new("html", "<Field label=\"T.C. Kimlik Numarası\" required>\n  <TurkiyeTcKimlikNumarasiInput label=\"T.C. Kimlik Numarası\" value={value} required />\n  <Hint>Eleven digits, the first never zero. The tenth digit is the units digit of ((sum of digits 1,3,5,7,9) × 7) plus ((sum of digits 2,4,6,8) × 9); the eleventh digit is the units digit of the sum of the first ten digits. The eleventh digit is always even.</Hint>\n  <ErrorMessage>Please enter a valid T.C. Kimlik Numarası</ErrorMessage>\n</Field>\n", new List<ExampleVariant> {  }),
